mutants.original_expression:
function createOrder(
        IERC20 sellToken,
        uint128 sellAmount,
        IERC20 buyToken,
        uint128 minBuyAmount,
        address buyer,
        uint40 expiryTime
    )
        external
        returns (uint256 orderId);

function fillOrder(
        uint256 orderId,
        uint128 buyAmount
    )
        external
        returns (
            uint128 amountToTransferToSeller,
            uint128 amountToTransferToBuyer,
            uint128 feeDeductedFromBuyerAmount,
            uint128 feeDeductedFromSellerAmount
        );

function setComptroller(ISablierComptroller newComptroller) external override onlyComptroller {

        _setComptroller({
            previousComptroller: comptroller,
            newComptroller: newComptroller,
            minimalInterfaceId: comptroller.MINIMAL_INTERFACE_ID()
        });
    }

function transferFeesToComptroller() external override {
        address comptrollerAddress = address(comptroller);
        uint256 feeAmount = address(this).balance;


        (bool success,) = comptrollerAddress.call{ value: feeAmount }("");



        success;


        emit IComptrollerable.TransferFeesToComptroller(comptrollerAddress, feeAmount);
    }

function getBuyer(uint256 orderId) external view override notNull(orderId) returns (address buyer) {
        buyer = _orders[orderId].buyer;
    }

function getBuyToken(uint256 orderId) external view override notNull(orderId) returns (IERC20 buyToken) {
        buyToken = _orders[orderId].buyToken;
    }

function getExpiryTime(uint256 orderId) external view override notNull(orderId) returns (uint40 expiryTime) {
        expiryTime = _orders[orderId].expiryTime;
    }

function getMinBuyAmount(uint256 orderId) external view override notNull(orderId) returns (uint128 minBuyAmount) {
        minBuyAmount = _orders[orderId].minBuyAmount;
    }

function getSellAmount(uint256 orderId) external view override notNull(orderId) returns (uint128 sellAmount) {
        sellAmount = _orders[orderId].sellAmount;
    }

function getSeller(uint256 orderId) external view override notNull(orderId) returns (address seller) {
        seller = _orders[orderId].seller;
    }

function getSellToken(uint256 orderId) external view override notNull(orderId) returns (IERC20 sellToken) {
        sellToken = _orders[orderId].sellToken;
    }

function statusOf(uint256 orderId) external view override notNull(orderId) returns (Escrow.Status status) {
        status = _statusOf(orderId);
    }

function wasCanceled(uint256 orderId) external view override notNull(orderId) returns (bool result) {
        result = _orders[orderId].wasCanceled;
    }

function wasFilled(uint256 orderId) external view override notNull(orderId) returns (bool result) {
        result = _orders[orderId].wasFilled;
    }

function cancelOrder(uint256 orderId) external override notNull(orderId) {
        Escrow.Order storage order = _orders[orderId];


        if (msg.sender != order.seller) {
            revert Errors_1.SablierEscrow_CallerNotAuthorized(orderId, msg.sender, order.seller);
        }


        if (order.wasFilled) {
            revert Errors_1.SablierEscrow_OrderFilled(orderId);
        }


        if (order.wasCanceled) {
            revert Errors_1.SablierEscrow_OrderCancelled(orderId);
        }


        order.wasCanceled = true;


        uint128 sellAmount = order.sellAmount;


        order.sellToken.safeTransfer(msg.sender, sellAmount);


        emit CancelOrder({ orderId: orderId, seller: msg.sender, sellAmount: sellAmount });
    }

function createOrder(
        IERC20 sellToken,
        uint128 sellAmount,
        IERC20 buyToken,
        uint128 minBuyAmount,
        address buyer,
        uint40 expiryTime
    )
        external
        override
        returns (uint256 orderId)
    {

        if (address(sellToken) == address(0)) {
            revert Errors_1.SablierEscrow_SellTokenZero();
        }


        if (address(sellToken) == nativeToken) {
            revert Errors_1.SablierEscrow_ForbidNativeToken(address(sellToken));
        }


        if (address(buyToken) == address(0)) {
            revert Errors_1.SablierEscrow_BuyTokenZero();
        }


        if (address(buyToken) == nativeToken) {
            revert Errors_1.SablierEscrow_ForbidNativeToken(address(buyToken));
        }


        if (sellToken == buyToken) {
            revert Errors_1.SablierEscrow_SameToken(sellToken);
        }


        if (sellAmount == 0) {
            revert Errors_1.SablierEscrow_SellAmountZero();
        }


        if (minBuyAmount == 0) {
            revert Errors_1.SablierEscrow_MinBuyAmountZero();
        }


        if (expiryTime > 0 && expiryTime <= block.timestamp) {
            revert Errors_1.SablierEscrow_ExpiryTimeInPast(expiryTime, uint40(block.timestamp));
        }


        orderId = nextOrderId;


        unchecked {
            nextOrderId = orderId + 1;
        }


        _orders[orderId] = Escrow.Order({
            seller: msg.sender,
            buyer: buyer,
            sellToken: sellToken,
            buyToken: buyToken,
            sellAmount: sellAmount,
            minBuyAmount: minBuyAmount,
            expiryTime: expiryTime,
            wasCanceled: false,
            wasFilled: false
        });


        sellToken.safeTransferFrom(msg.sender, address(this), sellAmount);


        emit CreateOrder({
            orderId: orderId,
            seller: msg.sender,
            buyer: buyer,
            sellToken: sellToken,
            buyToken: buyToken,
            sellAmount: sellAmount,
            minBuyAmount: minBuyAmount,
            expiryTime: expiryTime
        });
    }

function fillOrder(
        uint256 orderId,
        uint128 buyAmount
    )
        external
        override
        notNull(orderId)
        returns (
            uint128 amountToTransferToSeller,
            uint128 amountToTransferToBuyer,
            uint128 feeDeductedFromBuyerAmount,
            uint128 feeDeductedFromSellerAmount
        )
    {

        Escrow.Status status = _statusOf(orderId);
        if (status != Escrow.Status.OPEN) {
            revert Errors_1.SablierEscrow_OrderNotOpen(orderId, status);
        }

        Escrow.Order storage order = _orders[orderId];


        if (order.buyer != address(0) && msg.sender != order.buyer) {
            revert Errors_1.SablierEscrow_CallerNotAuthorized(orderId, msg.sender, order.buyer);
        }


        if (buyAmount < order.minBuyAmount) {
            revert Errors_1.SablierEscrow_InsufficientBuyAmount(buyAmount, order.minBuyAmount);
        }


        order.wasFilled = true;


        UD60x18 currentTradeFee = tradeFee;

        amountToTransferToSeller = buyAmount;
        amountToTransferToBuyer = order.sellAmount;


        if (currentTradeFee.unwrap_5() > 0) {

            feeDeductedFromBuyerAmount = ud(amountToTransferToBuyer).mul_1(currentTradeFee).intoUint128_5();
            amountToTransferToBuyer -= feeDeductedFromBuyerAmount;


            feeDeductedFromSellerAmount = ud(buyAmount).mul_1(currentTradeFee).intoUint128_5();
            amountToTransferToSeller -= feeDeductedFromSellerAmount;


            address feeRecipient = address(comptroller);


            order.buyToken.safeTransferFrom(msg.sender, feeRecipient, feeDeductedFromSellerAmount);
            order.sellToken.safeTransfer(feeRecipient, feeDeductedFromBuyerAmount);
        }


        address seller = order.seller;


        order.buyToken.safeTransferFrom(msg.sender, seller, amountToTransferToSeller);


        order.sellToken.safeTransfer(msg.sender, amountToTransferToBuyer);


        emit FillOrder({
            orderId: orderId,
            buyer: msg.sender,
            seller: seller,
            sellAmount: amountToTransferToBuyer,
            buyAmount: amountToTransferToSeller,
            feeDeductedFromBuyerAmount: feeDeductedFromBuyerAmount,
            feeDeductedFromSellerAmount: feeDeductedFromSellerAmount
        });
    }

function setNativeToken(address newNativeToken) external override onlyComptroller {

        if (newNativeToken == address(0)) {
            revert Errors_1.SablierEscrow_NativeTokenZeroAddress();
        }


        if (nativeToken != address(0)) {
            revert Errors_1.SablierEscrow_NativeTokenAlreadySet(nativeToken);
        }


        nativeToken = newNativeToken;


        emit SetNativeToken({ comptroller: msg.sender, nativeToken: newNativeToken });
    }

function setTradeFee(UD60x18 newTradeFee) external override onlyComptroller {

        _notTooHigh(newTradeFee);


        UD60x18 previousTradeFee = tradeFee;


        tradeFee = newTradeFee;


        emit SetTradeFee({ caller: msg.sender, previousTradeFee: previousTradeFee, newTradeFee: newTradeFee });
    }
